 * for plugin pages. Used by blog, CMS, and other plugins.
 */
export function PageLayout({
	children,
	className,
	"data-testid": dataTestId,
}: PageLayoutProps) {
	return (
		<div
			className={cn(
				"container mx-auto flex min-h-dvh flex-col items-center gap-12 px-4 py-18 lg:px-16",
				className,
